def ship_within_days(weights, days):
    def days_needed(cap):
        d, cur = 1, 0
        for w in weights:
            if cur + w > cap:                        # would overflow this day's capacity
                d += 1
                cur = 0
            cur += w
        return d

    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if days_needed(mid) <= days:
            hi = mid                                    # feasible, search for a smaller capacity
        else:
            lo = mid + 1                                 # infeasible, need more capacity
    return lo

